   149	    return null;
   150	  }
   151	
   152	  $depth = 0;
   153	  $started = false;
   154	  foreach ($tokens[0] as $entry) {
   155	    $token = strtolower((string) $entry[0]);
   156	    $offset = $openOffset + (int) $entry[1];
   157	    $isClose = str_starts_with($token, '</div');
   158	
   159	    if (!$started) {
   160	      if ($offset !== $openOffset) {
   161	        continue;
   162	      }
   163	      $started = true;
   164	      $depth = 1;
   165	      continue;
   166	    }
   167	
   168	    if ($isClose) {
   169	      $depth--;
   170	      if ($depth === 0) {
   171	        return $offset;
   172	      }
   173	      continue;
   174	    }
   175	
   176	    $depth++;
   177	  }
